"""Inventory: plain-assert pytest tests for inventory.units.parse_qty."""

from inventory.units import parse_qty


def test_plain_grams():
    assert parse_qty("250 g") == 250


def test_kilograms():
    assert parse_qty("3kg") == 3000


def test_fractional_kilograms():
    assert parse_qty("1.5 kg") == 1500


def test_rounds_to_nearest_gram():
    assert parse_qty("1.5g") == 2
    assert parse_qty("2.5g") == 3
    assert parse_qty("2.4g") == 2
    assert parse_qty("0.005 kg") == 5


def test_spacing_and_case_insensitive():
    assert parse_qty("  2KG ") == 2000
    assert parse_qty("1.0 kg") == 1000


def test_rejects_non_strings():
    for bad in (None, 3, 1.5, ["1kg"]):
        try:
            parse_qty(bad)
        except ValueError:
            pass
        else:
            raise AssertionError(f"Expected ValueError for {bad!r}")


def test_rejects_invalid_strings():
    for bad in ("", "3", "250", "1.5", "abc", "kg", "3 l", "3 lbs", "3kgx", "2kg5g", "-3kg"):
        try:
            parse_qty(bad)
        except ValueError:
            pass
        else:
            raise AssertionError(f"Expected ValueError for {bad!r}")


def test_error_message_is_helpful():
    try:
        parse_qty("nope")
    except ValueError as exc:
        assert "nope" in str(exc)
    else:
        raise AssertionError("Expected ValueError")

