def format_qty(grams):
    """Inventory: Render a gram count for display.

    Values of 1000 g or more are shown in kilograms with up to three
    decimals and no trailing zeros (1500 -> "1.5 kg", 2000 -> "2 kg");
    smaller values are shown as whole grams (250 -> "250 g").

    Args:
        grams: Non-negative whole number of grams.

    Returns:
        str: Human-readable quantity, e.g. "1.5 kg" or "250 g".

    Raises:
        ValueError: If grams is not a non-negative whole number of grams.
    """
    if isinstance(grams, (str, bytes, bool)):
        raise ValueError(f"Quantity must be a non-negative whole number of grams, got {grams!r}")
    try:
        value = Decimal(grams)
    except (TypeError, InvalidOperation) as exc:
        raise ValueError(f"Quantity must be a non-negative whole number of grams, got {grams!r}") from exc
    if not value.is_finite() or value < 0 or not value.is_integer():
        raise ValueError(f"Quantity must be a non-negative whole number of grams, got {grams!r}")
    if value >= Decimal(1000):
        kg_text = f"{value / Decimal(1000):.3f}".rstrip("0").rstrip(".")
        return f"{kg_text} kg"
    return f"{int(value)} g"

def test_error_message_is_helpful():
    try:
        parse_qty("nope")
    except ValueError as exc:
        assert "nope" in str(exc)
    else:
        raise AssertionError("Expected ValueError")


def test_format_grams_under_kilogram():
    assert format_qty(0) == "0 g"
    assert format_qty(250) == "250 g"
    assert format_qty(999) == "999 g"


def test_format_whole_kilograms_no_trailing_zeros():
    assert format_qty(1000) == "1 kg"
    assert format_qty(2000) == "2 kg"
    assert format_qty(15000) == "15 kg"


def test_format_kilograms_up_to_three_decimals():
    assert format_qty(1500) == "1.5 kg"
    assert format_qty(1001) == "1.001 kg"
    assert format_qty(1010) == "1.01 kg"
    assert format_qty(1234) == "1.234 kg"


def test_format_rejects_invalid_values():
    for bad in (None, "250", 250.5, -5, True, "1 kg", float("nan"), [1000]):
        try:
            format_qty(bad)
        except ValueError:
            pass
        else:
            raise AssertionError(f"Expected ValueError for {bad!r}")


def test_format_roundtrips_parse_qty():
    for text in ("1 kg", "1.5 kg", "2kg", "999 g", "250 g", "10 kg"):
        assert format_qty(parse_qty(text)) == text

